<?php

declare(strict_types=1);

namespace App\Policies;

use App\Models\Admin;
use Illuminate\Foundation\Auth\User as AuthUser;

/**
 * Generated by Shield, then extended by hand with the guard rails. The same
 * rules are enforced again in AdminService: the policy decides what the
 * panel offers, the service is what a caller cannot get around.
 */
final class AdminPolicy
{
    public function viewAny(AuthUser $actor): bool
    {
        return $actor->can('view_any:admin');
    }

    public function view(AuthUser $actor, Admin $admin): bool
    {
        return $actor->can('view:admin') && $this->maySee($actor, $admin);
    }

    public function create(AuthUser $actor): bool
    {
        return $actor->can('create:admin');
    }

    public function update(AuthUser $actor, Admin $admin): bool
    {
        return $actor->can('update:admin') && $this->mayManage($actor, $admin);
    }

    /**
     * Nobody deactivates their own account: they would be signed out on the
     * next request with no way to undo it.
     */
    public function deactivate(AuthUser $actor, Admin $admin): bool
    {
        return $this->update($actor, $admin) && ! $actor->is($admin);
    }

    public function delete(AuthUser $actor, Admin $admin): bool
    {
        return $actor->can('delete:admin')
            && $this->mayManage($actor, $admin)
            && ! $actor->is($admin);
    }

    /**
     * Super admin accounts are invisible to everyone but super admins.
     */
    private function maySee(AuthUser $actor, Admin $admin): bool
    {
        if (! $actor instanceof Admin) {
            return false;
        }

        return $actor->isSuperAdmin() || ! $admin->isSuperAdmin();
    }

    /**
     * Changing an account takes at least the permissions that account has.
     */
    private function mayManage(AuthUser $actor, Admin $admin): bool
    {
        return $actor instanceof Admin && $actor->hasAuthorityOver($admin);
    }
}
